  def install
    virtualenv_install_with_resources
    # The tray entry point is shipped as a standalone .app via the Cask
    # (`brew install --cask susops`); the Formula stays CLI/TUI-only.
    (bin/"susops-tray").unlink if (bin/"susops-tray").exist?
  end

  def caveats
    <<~EOS
      The macOS tray app is distributed separately as a Cask:
        brew install --cask susops

      If you install both, Homebrew won't symlink the CLI (same name as the cask), so `susops` won't be on your PATH. Link it with:
        brew link susops
    EOS
  end

  test do
    output = shell_output("#{bin}/susops ps 2>&1", 3)
    assert_match "stopped", output
  end
end
